async function loadPostMedia(postId,container){try{const media=await dbGet(`/postMedia/${postId}`);if(!container.isConnected)return;container.replaceChildren();if(media?.type==='imageData'&&String(media.value||'').startsWith('data:image/')){const img=document.createElement('img');img.alt='صورة المنشور';img.loading='lazy';img.src=media.value;container.append(img);if(Number(container.dataset.galleryCount)>1){const badge=document.createElement('span');badge.className='gallery-count';badge.textContent=`مجموعة ${container.dataset.galleryCount} صور`;container.append(badge)}}else if(media?.type==='imageUrl'){const url=httpsUrl(media.value);if(!url)throw new Error('BAD_MEDIA_URL');const img=document.createElement('img');img.alt='صورة المنشور';img.loading='lazy';img.referrerPolicy='no-referrer';img.src=url;img.onerror=()=>container.replaceChildren(Object.assign(document.createElement('div'),{className:'media-loading',textContent:'تعذر تحميل الصورة'}));container.append(img)}else if(media?.type==='videoUrl'){renderVideo(media.value,container)}else{container.append(Object.assign(document.createElement('div'),{className:'media-loading',textContent:'تعذر عرض الوسائط'}))}}catch(e){if(container.isConnected)container.replaceChildren(Object.assign(document.createElement('div'),{className:'media-loading',textContent:'تعذر تحميل الوسائط'}));console.warn('post media',e.firebaseCode||e.message)}}
function isImageMediaUrl(value){
 try{
  const u=new URL(String(value||''));
  if(u.protocol!=='https:')return false;
  const path=u.pathname.toLowerCase();
  if(/\.(?:jpe?g|png|gif|webp|avif|svg|bmp|ico|heic|heif)(?:$|\?)/i.test(path))return true;
  const host=u.hostname.toLowerCase();
  return host==='images.unsplash.com'||host==='images.pexels.com'||host==='i.imgur.com'||host.endsWith('.googleusercontent.com');
 }catch{return false}
}
