function timeLabel(value){const date=new Date(Number(value||0));if(Number.isNaN(date.getTime()))return'';return date.toLocaleString('ar',{dateStyle:'medium',timeStyle:'short'})}

function formatCount(value){const count=Math.max(0,Number(value)||0);return new Intl.NumberFormat('ar',{notation:'compact',maximumFractionDigits:1}).format(count)}
async function toggleLike(row,button){
 if(!session)return;
 const was=button.dataset.liked==='true';button.disabled=true;
 try{
  if(was)await dbDelete(`/likes/${row.id}/${session.user.id}`);else await dbPut(`/likes/${row.id}/${session.user.id}`,true);
  const count=Math.max(0,Number(button.dataset.count||0)+(was?-1:1));button.dataset.count=String(count);button.dataset.liked=String(!was);button.setAttribute('aria-pressed',String(!was));button.setAttribute('aria-label',`${!was?'إزالة إعجابك عن المنشور':'أعجب بهذا المنشور'} · ${formatCount(count)}`);button.classList.toggle('liked',!was);row.like_count=count;
  if(!feedLikes[row.id])feedLikes[row.id]={};if(was)delete feedLikes[row.id][session.user.id];else feedLikes[row.id][session.user.id]=true;
  setIconLabel(button,!was?'heart-fill':'heart',`${!was?'أعجبني':'إعجاب'} · ${formatCount(count)}`);
  if(!was){button.classList.remove('heart-burst');void button.offsetWidth;button.classList.add('heart-burst');window.setTimeout(()=>button.classList.remove('heart-burst'),650);notifyUser(row.author_id,'like',row.id,'أعجب بمنشورك').catch(()=>{});}
 }catch(e){toast('تعذر تحديث الإعجاب؛ تحقق من قواعد Firebase');console.warn('like',e.firebaseCode||e.message)}finally{button.disabled=false}
}
