async function compressImage(file,maxEdge,maxChars){
 if(!file||!file.type?.startsWith('image/'))throw new Error('اختر ملف صورة صالحًا.');
 if(file.size>18*1024*1024)throw new Error('حجم الصورة الأصلية كبير جدًا؛ اختر صورة أصغر من 18 ميغابايت.');
 const source=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(new Error('تعذرت قراءة الصورة من المعرض.'));reader.readAsDataURL(file)});
 const image=await new Promise((resolve,reject)=>{const img=new Image();img.onload=()=>resolve(img);img.onerror=()=>reject(new Error('صيغة الصورة غير مدعومة.'));img.src=source});
 if(!image.naturalWidth||!image.naturalHeight)throw new Error('تعذر التعرّف إلى أبعاد الصورة.');
 let scale=Math.min(1,maxEdge/Math.max(image.naturalWidth,image.naturalHeight));
 const jpeg=file.type.toLowerCase()==='image/jpeg';
 if(jpeg&&scale===1&&file.size<=Math.floor((maxChars-32)*.75))return source;
 for(let pass=0;pass<7;pass++){
  const canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(image.naturalWidth*scale));canvas.height=Math.max(1,Math.round(image.naturalHeight*scale));
  const ctx=canvas.getContext('2d');if(!ctx)throw new Error('تعذر ضغط الصورة على هذا الجهاز.');
  ctx.fillStyle='#fff';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.drawImage(image,0,0,canvas.width,canvas.height);
  for(const quality of [.84,.76,.68,.60,.52,.44]){const result=canvas.toDataURL('image/jpeg',quality);if(!result.startsWith('data:image/jpeg;base64,'))throw new Error('تعذر تحويل الصورة إلى صيغة مناسبة للنشر.');if(result.length<=maxChars)return result}
  scale*=.82;
 }
 throw new Error('لم نتمكن من ضغط الصورة إلى الحجم المناسب؛ جرّب صورة أصغر.');
}

function showImageEditor(){const modal=$('photoEditorModal');if(!modal)return;modal.classList.remove('hidden');drawPhotoEditor()}
function resetPhotoEditorControls(){editorRotation=0;$('photoRatio').value='original';$('photoSize').value='960';$('photoFilterPreset').value='none';$('photoBrightness').value='100';$('photoContrast').value='100';$('photoSaturation').value='100';['photoBrightnessValue','photoContrastValue','photoSaturationValue'].forEach(id=>{const output=$(id);if(output)output.value='100%'});$('photoCaption').value='';$('photoCaptionColor').value='white';$('photoCaptionPosition').value='bottom';drawPhotoEditor()}
function drawPhotoEditor(){
 if(!editorImage)return;
 const canvas=$('photoEditorCanvas'),ctx=canvas.getContext('2d');if(!ctx)return;
 const ratio=$('photoRatio').value||'original',edge=Number($('photoSize').value||960),rot=((editorRotation%360)+360)%360;
 const iw=rot%180?editorImage.naturalHeight:editorImage.naturalWidth,ih=rot%180?editorImage.naturalWidth:editorImage.naturalHeight;
 let w,h;if(ratio==='square'){w=h=edge}else if(ratio==='portrait'){w=Math.round(edge*.8);h=edge}else if(ratio==='story'){w=Math.round(edge*9/16);h=edge}else if(ratio==='landscape'){w=edge;h=Math.round(edge*9/16)}else{const scale=Math.min(1,edge/Math.max(iw,ih));w=Math.max(1,Math.round(iw*scale));h=Math.max(1,Math.round(ih*scale))}
 canvas.width=w;canvas.height=h;ctx.fillStyle='#fff';ctx.fillRect(0,0,w,h);
 const cover=Math.max(w/iw,h/ih),dw=editorImage.naturalWidth*cover,dh=editorImage.naturalHeight*cover;
 const presets={none:'',vivid:'saturate(1.25) contrast(1.08)',warm:'sepia(.16) saturate(1.12)',cool:'hue-rotate(8deg) saturate(1.12)',mono:'grayscale(1)',vintage:'sepia(.28) contrast(.94) saturate(.82)'};
 const brightness=Math.max(70,Math.min(130,Number($('photoBrightness').value)||100)),contrast=Math.max(70,Math.min(140,Number($('photoContrast').value)||100)),saturation=Math.max(0,Math.min(180,Number($('photoSaturation').value)));
 ctx.save();ctx.translate(w/2,h/2);ctx.rotate(rot*Math.PI/180);try{ctx.filter=`${presets[$('photoFilterPreset').value]||''} brightness(${brightness}%) contrast(${contrast}%) saturate(${saturation}%)`.trim()}catch{}ctx.drawImage(editorImage,-dw/2,-dh/2,dw,dh);ctx.restore();try{ctx.filter='none'}catch{}
 const caption=$('photoCaption').value.trim();if(caption){const maxW=w*.88,font=Math.max(18,Math.min(42,w/15));ctx.font=`700 ${font}px system-ui,sans-serif`;ctx.direction='rtl';ctx.textAlign='center';const words=caption.split(/\s+/),lines=[];let line='';for(const word of words){const next=line?line+' '+word:word;if(ctx.measureText(next).width>maxW&&line){lines.push(line);line=word}else line=next}if(line)lines.push(line);const lineH=font*1.32,pad=font*.5,shown=lines.slice(0,3),total=lineH*shown.length+pad*2,position=$('photoCaptionPosition').value,y0=position==='top'?12:position==='center'?(h-total)/2:h-total-12;ctx.save();ctx.fillStyle='#10101bd0';ctx.beginPath();const x=(w-maxW)/2-pad;ctx.roundRect(x,y0,maxW+pad*2,total,Math.min(18,font*.35));ctx.fill();const colors={white:'#fff',yellow:'#ffe08a',pink:'#ffc2dc',mint:'#aaf0df'};ctx.fillStyle=colors[$('photoCaptionColor').value]||'#fff';ctx.shadowColor='#0008';ctx.shadowBlur=3;shown.forEach((text,index)=>ctx.fillText(text,w/2,y0+pad+font+index*lineH,maxW));ctx.restore()}
}

function closePhotoEditor(save=false){$('photoEditorModal').classList.add('hidden');if(!save){pendingPostMedia=editorOldMedia;if(pendingPostMedia)updatePostMediaPreview(pendingPostMedia);else if(!$('postMediaUrl').value.trim()){$('postMediaPreview').replaceChildren();$('postMediaPreview').classList.add('hidden')}}editorImage=null;editorRotation=0;editorOldMedia=null}
function updatePostMediaPreview(data){const box=$('postMediaPreview');box.replaceChildren();box.classList.remove('hidden');if(pendingGalleryCount>1){const badge=document.createElement('span');badge.className='gallery-preview-count';badge.textContent=`معاينة مجموعة · ${pendingGalleryCount} صور`;box.append(badge)}const img=document.createElement('img');img.src=data;img.alt=pendingGalleryCount>1?`مجموعة صور مدمجة، ${pendingGalleryCount} صور`:'معاينة الصورة المعدّلة';box.append(img);const edit=document.createElement('button');edit.type='button';edit.className='inline-btn';edit.textContent='✎ تعديل الصورة';edit.onclick=()=>{editorOldMedia=pendingPostMedia;const im=new Image();im.onload=()=>{editorImage=im;resetPhotoEditorControls();showImageEditor()};im.src=pendingPostMedia};const remove=document.createElement('button');remove.type='button';remove.className='preview-remove';remove.textContent='×';remove.setAttribute('aria-label','إزالة الصورة');remove.onclick=clearPostMedia;box.append(edit,remove)}
function applyPhotoEdits(){
 if(!editorImage)return;
 try{
  const canvas=$('photoEditorCanvas');let data='';
  for(let pass=0;pass<6;pass++){
   for(const quality of [.84,.74,.64,.54,.46]){data=canvas.toDataURL('image/jpeg',quality);if(data.length<=330000)break}
   if(data.length<=330000)break;
   if(canvas.width<360||canvas.height<360)break;
   const smaller=document.createElement('canvas');smaller.width=Math.max(1,Math.round(canvas.width*.82));smaller.height=Math.max(1,Math.round(canvas.height*.82));smaller.getContext('2d').drawImage(canvas,0,0,smaller.width,smaller.height);canvas.width=smaller.width;canvas.height=smaller.height;canvas.getContext('2d').drawImage(smaller,0,0);
  }
  if(!data.startsWith('data:image/jpeg;base64,')||data.length>330000)throw new Error('حجم الصورة المعدّلة تجاوز حد النشر؛ اختر دقة أقل.');
  pendingPostMedia=data;$('postMediaUrl').value='';$('postMediaUrl').classList.add('hidden');closePhotoEditor(true);updatePostMediaPreview(data);status('postStatus','تم حفظ التعديلات وضغط الصورة تلقائيًا لتسريع النشر.','ok');
 }catch(e){status('photoEditorStatus',e.message||'تعذر حفظ التعديلات.','error')}
}

async function preparePostImage(file){
 if(!file)return;
 if(!file.type?.startsWith('image/')){status('postStatus','اختر ملف صورة صالحًا.','error');return}
 if(file.size>18*1024*1024){status('postStatus','حجم الصورة الأصلية كبير؛ اختر صورة أصغر من 18 ميغابايت.','error');return}
 status('postStatus','جارٍ ضغط الصورة تلقائيًا قبل تجهيزها للنشر…');
 try{
  const saver=isDataSaverEnabled(),edge=saver?960:1280,target=saver?260000:330000;
  const data=await compressImage(file,edge,target);
  const encoded=data.slice(data.indexOf(',')+1),padding=encoded.endsWith('==')?2:encoded.endsWith('=')?1:0;
  const outputBytes=Math.max(0,Math.floor(encoded.length*3/4)-padding),beforeKb=Math.ceil(file.size/1024),afterKb=Math.ceil(outputBytes/1024),savedKb=Math.max(0,Math.floor((file.size-outputBytes)/1024));
  pendingPostMedia=data;pendingGalleryCount=0;$('postMediaUrl').value='';$('postMediaUrl').classList.add('hidden');updatePostMediaPreview(data);
  const detail=savedKb?`من ${beforeKb} إلى ${afterKb} كيلوبايت (توفير ${savedKb} كيلوبايت)`:`بحجم ${afterKb} كيلوبايت`;
  status('postStatus',`ضُغطت الصورة تلقائيًا ${detail}؛ أصبحت جاهزة للنشر. يمكنك تعديلها قبل النشر.`,'ok');
 }catch(e){status('postStatus',e.message||'تعذر ضغط الصورة وتجهيزها.','error')}
 finally{$('postImageInput').value=''}
}

