function renderChatAttachmentPreview(){const box=$('chatImagePreview');if(!box)return;box.replaceChildren();box.classList.toggle('hidden',!pendingChatImage);$('chatSystemShare')?.classList.toggle('hidden',!pendingChatImage);if(!pendingChatImage)return;const img=document.createElement('img');img.src=pendingChatImage;img.alt='معاينة مرفق المحادثة';const remove=document.createElement('button');remove.type='button';remove.textContent='×';remove.setAttribute('aria-label','إزالة المرفق');remove.onclick=()=>{pendingChatImage=null;lastChatImage=null;renderChatAttachmentPreview()};box.append(img,remove)}
function shareChatAttachment(){const data=pendingChatImage||lastChatImage;if(!data){toast('أرفق صورة أولًا لمشاركتها مع جهاز قريب');return}if(window.MoadbookSecureStore?.shareImage){window.MoadbookSecureStore.shareImage(data,'moadbook-chat.jpg');return}toast('مشاركة الملفات عبر Bluetooth متاحة من تطبيق Android')}
function syncNativePushToken(){try{const token=window.MoadbookSecureStore?.getPushToken?.();if(!token||!session)return;const key=btoa(token).replace(/\+/g,'-').replace(/\//g,'_').replace(/=+$/,'');dbPut(`/pushTokens/${session.user.id}/${key}`,{token,updatedAt:Date.now()}).catch(e=>console.warn('push token registration',e.firebaseCode||e.message))}catch(e){console.warn('push token unavailable')}}
async function enablePhoneNotifications(){const bridge=window.MoadbookSecureStore;if(bridge?.requestNotificationPermission){bridge.requestNotificationPermission();status('pushStatus','تم طلب إذن Android. إشعارات الخلفية تتطلب مرسل FCM موثوقًا على الخادم.');setTimeout(()=>{syncNativePushToken();status('pushStatus','إذا لم يظهر الإذن، فعّله من إعدادات Android.')},1800);return}if(!session){status('pushStatus','سجّل الدخول أولًا لتفعيل الإشعارات.','error');return}if(!('Notification'in window)){status('pushStatus','هذا المتصفح لا يدعم إشعارات الويب.','error');return}if(!window.isSecureContext){status('pushStatus','تحتاج إشعارات الويب إلى HTTPS أو localhost.','error');return}try{const permission=await Notification.requestPermission();if(permission!=='granted'){status('pushStatus',permission==='denied'?'رُفض الإذن؛ فعّله من إعدادات الموقع.':'لم تمنح إذن الإشعارات.','error');return}let backgroundReady=false;if('serviceWorker'in navigator&&window.MOADBOOK_WEB_PUSH_PUBLIC_KEY){try{const registration=await navigator.serviceWorker.ready;backgroundReady=await subscribeWebPush(registration)}catch(e){console.warn('web push subscription',e.firebaseCode||e.message)}}status('pushStatus',backgroundReady?'تم تفعيل إشعارات الويب وتسجيل هذا الجهاز للإشعارات الخلفية.':'تم تفعيل تنبيهات المتصفح أثناء تشغيل التطبيق. لإشعارات الخلفية، أضف مفتاح VAPID العام وانشر وظيفة Web Push وقواعد Firebase المرفقة.');toast('تم تفعيل إذن إشعارات المتصفح')}catch(e){status('pushStatus','تعذر تفعيل الإشعارات. تحقق من إعدادات الموقع وHTTPS.','error');console.warn('web notification permission',e.message)}}
function previewMediaUrl(value){const box=$('postMediaPreview'),url=httpsUrl(value);if(!url){box.replaceChildren();box.classList.add('hidden');return}pendingPostMedia=null;pendingGalleryCount=0;box.replaceChildren();box.classList.remove('hidden');if(isVideoMediaUrl(url)){renderVideo(url,box)}else if(isImageMediaUrl(url)){const img=document.createElement('img');img.src=url;img.alt='معاينة الوسائط';img.loading='lazy';img.referrerPolicy='no-referrer';img.onerror=()=>{box.replaceChildren(Object.assign(document.createElement('div'),{className:'media-loading',textContent:'تعذر تحميل معاينة الصورة'}))};box.append(img)}else{const note=document.createElement('div');note.className='media-loading';note.textContent='لا تتوفر معاينة مباشرة لهذا الرابط؛ سيظهر كرابط قابل للفتح.';box.append(note)}const remove=document.createElement('button');remove.className='preview-remove';remove.type='button';remove.textContent='×';remove.setAttribute('aria-label','إزالة الرابط');remove.onclick=clearPostMedia;box.append(remove)}
function postPublishErrorText(error,stage='create-post'){
 const code=String(error?.firebaseCode||error?.message||'').toUpperCase();
 if(code.includes('PERMISSION_DENIED')||code.includes('PERMISSION DENIED')){
  if(stage==='save-media')return 'رفضت قواعد Firebase حفظ الصورة في /postMedia. صورة الحساب تستخدم /profileMedia بصلاحيات مختلفة. انشر قواعد Firebase المرفقة للإصدار 1.10.3 ثم أعد المحاولة.';
  if(stage==='create-post')return 'رفضت قواعد Firebase إنشاء المنشور في /posts. انشر قواعد الإصدار 1.10.3 ثم أعد المحاولة.';
  if(stage==='save-poll')return 'رفضت قواعد Firebase حفظ الاستطلاع. انشر قواعد الإصدار 1.10.3 ثم أعد المحاولة.';
  return 'رفضت قواعد Firebase خطوة من خطوات النشر. راجع قواعد الإصدار 1.10.3؛ بقي النص والصورة في المحرر.';
 }
 if(code.includes('FAILED TO FETCH')||code.includes('NETWORK')||code.includes('TIMEOUT'))return 'انقطع الاتصال بـ Firebase أثناء النشر. تحقق من الإنترنت ثم أعد المحاولة؛ بقيت الصورة والنص في المحرر.';
 if(code.includes('QUOTA')||code.includes('TOO LARGE')||code.includes('PAYLOAD'))return 'رفض Firebase حجم بيانات الصورة. قلّل عدد الصور أو فعّل توفير البيانات ثم أعد المحاولة.';
 if(code.includes('FIREBASE_CONFIG_MISSING'))return 'إعداد الاتصال بقاعدة Firebase غير موجود في هذه النسخة.';
 return `لم يكتمل النشر (${stage}). بقي النص والصورة في المحرر. رمز التشخيص: ${String(error?.firebaseCode||error?.message||'UNKNOWN').slice(0,100)}.`;
}
async function publishPost(){
 const context=composeGroupContext?{...composeGroupContext}:null;
 const body=$('postInput').value.trim(),mediaUrl=httpsUrl($('postMediaUrl').value),postType=$('postType').value||'general',postFont=$('postFont')?.value||'tajawal',galleryCount=pendingGalleryCount||0;
 if($('postMediaUrl').value.trim()&&!mediaUrl){status('postStatus','يجب أن يبدأ الرابط بـ https://.','error');return}
 const pollOptions=[0,1,2,3].map(i=>$(`pollOption${i}`).value.trim()).filter(Boolean);
 if(postType==='poll'){const unique=new Set(pollOptions.map(x=>x.toLocaleLowerCase('ar')));if(!body){status('postStatus','اكتب سؤال الاستطلاع أولًا.','error');return}if(pollOptions.length<2||pollOptions.length>4||unique.size!==pollOptions.length){status('postStatus','أضف خيارين مختلفين على الأقل، وحتى 4 خيارات.','error');return}}
 if(!body&&!pendingPostMedia&&!mediaUrl){status('postStatus','اكتب شيئًا أو أرفق صورة/رابطًا.','error');return}
 const hiddenMeta=`\u2063mbfont:${postFont}\u2063${galleryCount>1?`\u2063mbgallery:${galleryCount}\u2063`:''}`;
 if(body.length+hiddenMeta.length>2000){status('postStatus','قلّل النص قليلًا لإضافة بيانات الخط/المجموعة ضمن حد Firebase.','error');return}
 if(!session){showScreen('authScreen');return}
 if(context){try{const[group,member]=await Promise.all([dbGet(`/groups/${context.id}`),dbGet(`/groupMembers/${context.id}/${session.user.id}`)]);if(!group||(!member&&group.ownerId!==session.user.id)){status('postStatus','انضم إلى المجموعة أولًا قبل النشر فيها.','error');return}}catch(e){status('postStatus','تعذر التحقق من عضويتك. طبّق قواعد RTDB المحدّثة ثم حاول.','error');return}}
 const storedBody=hiddenMeta+body;
 $('publishButton').disabled=true;status('postStatus','جارٍ النشر…');let postId=null,publishStage='create-post';
 try{
  let mediaType='',mediaValue='';if(pendingPostMedia){mediaType='imageData';mediaValue=pendingPostMedia}else if(mediaUrl){mediaType=isImageMediaUrl(mediaUrl)?'imageUrl':'videoUrl';mediaValue=mediaUrl}
  const post={authorId:session.user.id,authorName:nameOf().slice(0,60),body:storedBody,postType,createdAt:Date.now(),hasMedia:!!mediaType,mood:$('postMood').value||'',...(context?{groupId:context.id}:{})};
  const result=await dbPost('/posts',post);postId=result.name;
  try{if(mediaType){publishStage='save-media';await dbPut(`/postMedia/${postId}`,{authorId:session.user.id,type:mediaType,value:mediaValue,createdAt:Date.now()})}if(postType==='poll'){publishStage='save-poll';const options={};pollOptions.forEach((label,index)=>options[String(index)]=label);await dbPut(`/polls/${postId}`,{authorId:session.user.id,createdAt:Date.now(),options})}}
  catch(e){await Promise.all([dbDelete(`/postMedia/${postId}`).catch(()=>{}),dbDelete(`/polls/${postId}`).catch(()=>{}),dbDelete(`/posts/${postId}`).catch(()=>{})]);throw e}
  $('postInput').value='';$('postType').value='general';$('postMood').value='';[0,1,2,3].forEach(i=>$(`pollOption${i}`).value='');updatePollEditor();$('charCount').textContent='0';clearPostMedia();try{localStorage.removeItem(`moadbook-draft-${session.user.id}`)}catch(e){}
  status('postStatus','تم النشر.','ok');loadFeed(true);
  if(context){setComposeGroupContext('','');window.setTimeout(()=>window.MoadbookGroups?.openGroup(context.id),80)}else window.scrollTo({top:0,behavior:'smooth'});
 }catch(e){status('postStatus',context&&publishStage==='create-post'?'تعذر النشر داخل المجموعة. تأكد من تطبيق قواعد RTDB الجديدة وأن عضويتك فعالة.':postPublishErrorText(e,publishStage),'error');console.warn('publish stage',publishStage,e.firebaseCode||e.message)}
 finally{$('publishButton').disabled=false}
}
async function deletePost(id){confirmApp('حذف المنشور؟','سيُحذف المنشور وتفاعلاته نهائيًا ولا يمكن التراجع عن ذلك.',()=>deletePostNow(id),{danger:true,confirmLabel:'حذف'});}
async function deletePostNow(id){try{const[likes,comments]=await Promise.all([safeGet(`/likes/${id}`,{}),safeGet(`/comments/${id}`,{})]);await Promise.all([dbDelete(`/postMedia/${id}`).catch(()=>{}),dbDelete(`/polls/${id}`).catch(()=>{}),dbDelete(`/pollVotes/${id}`).catch(()=>{})]);await Promise.all([...Object.keys(likes||{}).map(uid=>dbDelete(`/likes/${id}/${uid}`).catch(()=>{})),...Object.keys(comments||{}).map(cid=>dbDelete(`/comments/${id}/${cid}`).catch(()=>{}))]);await dbDelete(`/posts/${id}`);delete pollCache[id];delete pollVoteCache[id];toast('تم حذف المنشور');await loadFeed(true)}catch(e){toast('تعذر حذف المنشور أو تفاعلاته؛ تحقق من قواعد Firebase');console.warn('delete post',e.firebaseCode||e.message)}}
function basicRow(title,sub,initial,actionText='',action=null){const card=document.createElement('div');card.className='card list-card';const avatar=document.createElement('div');avatar.className='avatar';avatar.textContent=[...(initial||title||'م')][0]||'م';const main=document.createElement('div');main.className='list-main';const name=document.createElement('div');name.className='list-title';name.textContent=title;const description=document.createElement('div');description.className='list-sub';description.textContent=sub||'';main.append(name,description);card.append(avatar,main);if(actionText&&action){const button=document.createElement('button');button.className='inline-btn';button.textContent=actionText;button.onclick=action;card.append(button)}return card}
function profileRow(title,sub,person,actionText='',action=null){const card=document.createElement('div');card.className='card list-card';card.dataset.search=`${title} ${sub}`.toLowerCase();const av=document.createElement('div');av.className='avatar';setAvatar(av,person);av.onclick=event=>{event.stopPropagation();openPerson(person.id)};const main=document.createElement('div');main.className='list-main';const t=document.createElement('div');t.className='list-title';t.textContent=title;t.onclick=event=>{event.stopPropagation();openPerson(person.id)};const s=document.createElement('div');s.className='list-sub';s.textContent=sub||'عضو في moadbook';main.append(t,s);card.append(av,main);if(actionText&&action){const b=document.createElement('button');b.className='inline-btn';b.textContent=actionText;b.onclick=action;card.append(b)}return card}
function profileActionsRow(person,relation,following=false){const card=document.createElement('div');card.className='card list-card';card.dataset.search=`${person.displayName||''} ${person.username||''} ${person.bio||''}`.toLowerCase();const av=document.createElement('div');av.className='avatar';setAvatar(av,person);av.onclick=event=>{event.stopPropagation();openPerson(person.id)};const main=document.createElement('div');main.className='list-main';const title=document.createElement('div');title.className='list-title';title.textContent=person.displayName||person.username||'عضو';title.onclick=()=>openPerson(person.id);const sub=document.createElement('div');sub.className='list-sub';sub.textContent=person.bio||'عضو في moadbook';main.append(title,sub);const actions=document.createElement('div');actions.className='list-actions';const follow=document.createElement('button');follow.className='inline-btn';follow.textContent=following?'تتابعه':'متابعة';follow.onclick=async()=>{await toggleFollow(person.id);await loadFriends()};actions.append(follow);const friend=document.createElement('button');friend.className='inline-btn';if(relation?.status==='accepted'){friend.textContent='صديق';friend.disabled=true}else if(relation?.status==='pending'&&relation.requesterId===session.user.id){friend.textContent='بانتظار الرد';friend.disabled=true}else if(relation?.status==='pending'&&relation.recipientId===session.user.id){friend.textContent='قبول';friend.onclick=()=>acceptFriend(relation)}else{friend.textContent='إضافة';friend.onclick=()=>sendFriendRequest(person.id)}actions.append(friend);card.append(av,main,actions);return card}
async function acceptFriend(relation){try{const{id,...row}=relation;await dbPut(`/friendships/${id}`,{...row,status:'accepted'});await notifyUser(relation.requesterId,'friend_accept',id,'قبل طلب صداقتك');toast('أصبحتما صديقين');await loadFriends()}catch(e){toast('تعذر قبول الطلب؛ تحقق من القواعد');console.warn(e.firebaseCode||e.message)}}
async function sendFriendRequest(targetId){try{await dbPut(`/friendships/${friendshipKey(session.user.id,targetId)}`,{requesterId:session.user.id,recipientId:targetId,status:'pending',createdAt:Date.now()});await notifyUser(targetId,'friend_request',friendshipKey(session.user.id,targetId),'أرسل لك طلب صداقة');toast('تم إرسال طلب الصداقة');await loadFriends()}catch(e){toast('تعذر إرسال الطلب أو أن هناك طلبًا سابقًا');console.warn(e.firebaseCode||e.message)}}
async function toggleFollow(targetId){if(!session||targetId===session.user.id)return;try{const path=`/follows/${session.user.id}/${targetId}`;const existing=await safeGet(path,false);if(existing){await dbDelete(path);toast('ألغيت المتابعة')}else{await dbPut(path,true);await notifyUser(targetId,'follow',targetId,'بدأ بمتابعتك');toast('بدأت بمتابعة هذا العضو')}}catch(e){toast('تعذر تحديث المتابعة؛ انشر القواعد المحدّثة');console.warn('follow',e.firebaseCode||e.message)}}
async function loadFriends(){const box=$('friendsList');if(!box.childElementCount)box.replaceChildren(emptyCard('جارٍ العثور على أعضاء…'));if(!session)return;try{const[peopleData,relationsData,followingData]=await Promise.all([dbGet('/profiles'),dbGet('/friendships'),safeGet(`/follows/${session.user.id}`,{})]);const people=mapRows(peopleData).filter(person=>person.id!==session.user.id&&!blockedUsers[person.id]).sort((a,b)=>String(a.displayName||'').localeCompare(String(b.displayName||''),'ar'));const relations=mapRows(relationsData);box.replaceChildren();if(!people.length){box.append(emptyCard('لا يوجد أعضاء بعد','عندما ينضم أعضاء جدد سيظهرون هنا.'));return}for(const person of people){profileCache[person.id]=person;const relation=relations.find(r=>(r.requesterId===person.id&&r.recipientId===session.user.id)||(r.requesterId===session.user.id&&r.recipientId===person.id));box.append(profileActionsRow({...person,id:person.id},relation,!!followingData?.[person.id]))}filterPeople()}catch(e){box.replaceChildren(emptyCard('تعذر تحميل الأعضاء','تحقق من اتصال Firebase ثم حاول مجددًا.'));console.warn('friends',e.firebaseCode||e.message)}}
