async function loadProfileById(uid){if(profileCache[uid])return profileCache[uid];const row=await dbGet(`/profiles/${uid}`);if(row){profileCache[uid]={...row,id:uid};return profileCache[uid]}return null}
async function openPerson(uid){if(!uid||!session)return;if(uid===session.user.id){navigate('profile');return}if(blockedUsers[uid]){toast('هذا الحساب محظور لديك؛ ألغِ الحظر من إعدادات الخصوصية أولًا.');return}currentPersonId=uid;personReturnPage=currentPage==='person'?personReturnPage:currentPage;showPage('person');$('personProfile').replaceChildren(emptyCard('جارٍ تحميل الملف الشخصي…'));$('personPosts').replaceChildren();$('personFriends').replaceChildren();try{const[person,postsData,followsData,relationsData,profilesData]=await Promise.all([loadProfileById(uid),safeGet('/posts',{}, {orderBy:'"authorId"',equalTo:JSON.stringify(uid)}),safeGet('/follows',{}),safeGet('/friendships',{}),safeGet('/profiles',{})]);if(!person){$('personProfile').replaceChildren(emptyCard('لم نعثر على هذا الحساب'));return}const posts=mapRows(postsData).sort((a,b)=>Number(b.createdAt||0)-Number(a.createdAt||0)).map(row=>postFromFirebase(row.id,row));const follows=followsData||{},relations=mapRows(relationsData);const followers=Object.keys(follows).filter(id=>!!follows[id]?.[uid]).length;const following=Object.keys(follows[uid]||{}).length;const friends=relations.filter(r=>r.status==='accepted'&&(r.requesterId===uid||r.recipientId===uid));const profiles=profilesData||{};const friendPeople=friends.map(r=>{const id=r.requesterId===uid?r.recipientId:r.requesterId;return profiles[id]?{...profiles[id],id}:null}).filter(Boolean);const relation=relations.find(r=>(r.requesterId===uid&&r.recipientId===session.user.id)||(r.requesterId===session.user.id&&r.recipientId===uid));renderPersonHeader(person,{posts:posts.length,friends:friendPeople.length,followers,following},relation,!!follows[session.user.id]?.[uid]);const liked=new Set(posts.filter(row=>feedLikes[row.id]?.[session.user.id]).map(row=>row.id));renderFeed(posts,$('personPosts'),liked);const friendsBox=$('personFriends');friendsBox.replaceChildren();if(friendPeople.length)for(const friend of friendPeople)friendsBox.append(profileRow(friend.displayName||friend.username,friend.bio,friend));else friendsBox.append(emptyCard('لا توجد صداقات معروضة بعد'))}catch(e){$('personProfile').replaceChildren(emptyCard('تعذر تحميل الملف الشخصي','تحقق من قواعد Firebase المحدّثة.'));console.warn('person profile',e.firebaseCode||e.message)}}
function renderPersonHeader(person,stats,relation,following){const box=$('personProfile');box.replaceChildren();const hero=document.createElement('div');hero.className='profile-hero';const cover=document.createElement('div');cover.className='profile-cover';const coverLabel=document.createElement('span');coverLabel.className='profile-cover-label';coverLabel.textContent='مساحة أفكارك · moadbook';cover.append(coverLabel);hero.append(cover);const avatar=document.createElement('div');avatar.className='avatar profile-large';setAvatar(avatar,{...person,id:currentPersonId});const name=document.createElement('strong');name.textContent=person.displayName||person.username||'عضو';window.MoadbookAdmin?.decorateVerified?.(currentPersonId,name);const handle=document.createElement('div');handle.className='muted';handle.textContent='@'+(person.username||'عضو');const bio=document.createElement('p');bio.className='muted';bio.textContent=person.bio||'لم يضف نبذة بعد.';const statsRow=document.createElement('div');statsRow.className='stats-row';for(const[label,value]of[['منشور',stats.posts],['أصدقاء',stats.friends],['متابعون',stats.followers],['يتابع',stats.following]]){const stat=document.createElement('div');stat.className='stat';const strong=document.createElement('strong');strong.textContent=String(value);const caption=document.createElement('span');caption.textContent=label;stat.append(strong,caption);statsRow.append(stat)}const actions=document.createElement('div');actions.className='person-actions';const followBtn=document.createElement('button');followBtn.className='btn light';followBtn.textContent=following?'إلغاء المتابعة':'متابعة';followBtn.onclick=async()=>{await toggleFollow(currentPersonId);openPerson(currentPersonId)};actions.append(followBtn);const friendBtn=document.createElement('button');friendBtn.className='btn light';if(relation?.status==='accepted'){friendBtn.textContent='صديق ✓';friendBtn.disabled=true}else if(relation?.status==='pending'&&relation.recipientId===session.user.id){friendBtn.textContent='قبول طلب الصداقة';friendBtn.onclick=async()=>{await acceptFriend(relation);openPerson(currentPersonId)}}else if(relation?.status==='pending'){friendBtn.textContent='الطلب قيد الانتظار';friendBtn.disabled=true}else{friendBtn.textContent='إضافة صديق';friendBtn.onclick=()=>sendFriendRequest(currentPersonId)}actions.append(friendBtn);const blockBtn=document.createElement('button');blockBtn.className='btn light';blockBtn.textContent=blockedUsers[currentPersonId]?'إلغاء الحظر':'حظر';blockBtn.onclick=async()=>{const uid=currentPersonId;await toggleBlockUser(uid);if(blockedUsers[uid])navigate('friends');else openPerson(uid)};actions.append(blockBtn);const reportBtn=document.createElement('button');reportBtn.className='btn light';reportBtn.textContent='إبلاغ';reportBtn.onclick=()=>reportContent('user',currentPersonId);actions.append(reportBtn);if(relation?.status==='accepted'){const message=document.createElement('button');message.className='btn primary';message.textContent='إرسال رسالة';message.onclick=()=>openChat(person);actions.append(message)}hero.append(avatar,name,handle,bio,statsRow,actions);box.append(hero)}
async function loadGroups(){
 if(window.MoadbookGroups?.loadGroups)return window.MoadbookGroups.loadGroups();
 const box=$('groupsList');if(!box)return;if(!session){box.replaceChildren(emptyCard('سجّل الدخول لاستكشاف المجتمعات'));return}
 if(!box.childElementCount)box.replaceChildren(emptyCard('جارٍ تحميل المجتمعات…'));
 try{const[groupsData,membersData]=await Promise.all([dbGet('/groups'),dbGet('/groupMembers')]);communityDirectoryRows=mapRows(groupsData).map(g=>({...g,category:g.category||'عام'}));communityMemberRows=membersData||{};renderCommunityDirectory()}catch(e){box.replaceChildren(emptyCard('تعذر تحميل المجتمعات','تحقق من قواعد Firebase ثم حدّث الصفحة.'));console.warn('communities',e.firebaseCode||e.message)}
}
let communityDirectoryRows=[],communityMemberRows={};
function renderCommunityDirectory(){
 if(window.MoadbookGroups?.renderCommunityDirectory)return window.MoadbookGroups.renderCommunityDirectory();
 const box=$('groupsList');if(!box)return;const query=($('communitySearch')?.value||'').trim().toLocaleLowerCase('ar'),category=$('communityCategoryFilter')?.value||'all';
 const rows=communityDirectoryRows.map(g=>({...g,memberCount:Object.keys(communityMemberRows[g.id]||{}).length,joined:!!communityMemberRows[g.id]?.[session?.user?.id]})).filter(g=>(category==='all'||g.category===category)&&(!query||`${g.name} ${g.description} ${g.category}`.toLocaleLowerCase('ar').includes(query))).sort((a,b)=>b.memberCount-a.memberCount||Number(b.createdAt||0)-Number(a.createdAt||0));
 const joined=communityDirectoryRows.filter(g=>!!communityMemberRows[g.id]?.[session?.user?.id]).length;$('communitySummary').textContent=`${communityDirectoryRows.length} مجتمع · أنت عضو في ${joined} · الترتيب حسب عدد الأعضاء الفعلي ثم الأحدث`;
 box.replaceChildren();if(!rows.length){box.append(emptyCard(query||category!=='all'?'لا توجد نتائج مطابقة':'لا توجد مجتمعات بعد','أنشئ مجتمعًا عامًا وابدأ بدعوة المهتمين.'));return}
 for(const group of rows){const card=document.createElement('article');card.className='community-card';const head=document.createElement('div');head.className='community-card-head';const avatar=document.createElement('div');avatar.className='community-avatar';avatar.textContent=Array.from(group.name||'م')[0]||'م';const main=document.createElement('div');main.style.minWidth='0';const title=document.createElement('div');title.className='community-card-title';title.textContent=group.name||'مجتمع';const desc=document.createElement('div');desc.className='community-card-desc';desc.textContent=group.description||'مجتمع moadbook للنقاش وتبادل المعرفة.';head.append(avatar,main);main.append(title,desc);const meta=document.createElement('div');meta.className='community-meta';for(const value of [`${group.memberCount} عضو`,group.category||'عام',group.ownerId===session?.user?.id?'أنت المالك':'مجتمع عام']){const pill=document.createElement('span');pill.className='community-pill';pill.textContent=value;meta.append(pill)}card.append(head,meta);const actions=document.createElement('div');actions.className='community-actions';const join=document.createElement('button');join.type='button';join.className=group.joined?'btn light':'btn primary';const isOwner=group.ownerId===session?.user?.id;join.textContent=isOwner?(group.joined?'أنت المالك':'استعادة عضوية المالك'):group.joined?'مغادرة المجتمع':'انضمام';join.disabled=isOwner&&group.joined;join.onclick=async()=>{join.disabled=true;try{if(isOwner&&!group.joined){await dbPut(`/groupMembers/${group.id}/${session.user.id}`,'owner');toast('تم استعادة عضوية المالك')}else if(group.joined){await dbDelete(`/groupMembers/${group.id}/${session.user.id}`);toast('غادرت المجتمع')}else{await dbPut(`/groupMembers/${group.id}/${session.user.id}`,'member');if(group.ownerId!==session.user.id)await notifyUser(group.ownerId,'group_member',group.id,'انضم إلى مجتمعك');toast('انضممت إلى المجتمع')}await loadGroups()}catch(e){toast('تعذر تحديث العضوية. تحقق من قواعد RTDB.');console.warn('community membership',e.firebaseCode||e.message)}finally{join.disabled=false}};actions.append(join);if(group.ownerId===session?.user?.id){const edit=document.createElement('button');edit.type='button';edit.className='btn light';edit.textContent='تعديل الوصف';edit.onclick=()=>showAppDialog({title:'تعديل وصف المجتمع',message:'اكتب وصفًا مختصرًا وواضحًا للمجتمع.',confirmLabel:'حفظ التعديل',input:true,inputValue:group.description||'',placeholder:'وصف المجتمع (حتى 240 حرفًا)…',onConfirm:async value=>{try{await dbPut(`/groups/${group.id}/description`,String(value||'').slice(0,240));closeAppDialog();toast('تم تحديث وصف المجتمع','success');await loadGroups()}catch(e){toast('تعذر الحفظ؛ قد تحتاج إلى نشر قواعد 1.10.5.','error');console.warn('community edit',e.firebaseCode||e.message)}}});actions.append(edit)}card.append(actions);box.append(card)}
}
async function createGroup(){if(window.MoadbookGroups?.createGroup)return window.MoadbookGroups.createGroup();const name=$('groupName').value.trim(),description=$('groupDescription').value.trim(),category=$('groupCategory')?.value||'عام';if(name.length<2){status('groupStatus','اسم المجتمع يجب أن يكون حرفين على الأقل.','error');return}if(!session)return;$('createGroupButton').disabled=true;status('groupStatus','جارٍ التحقق وإنشاء المجتمع…');try{const existingGroups=mapRows(await dbGet('/groups'));if(existingGroups.some(g=>String(g.name||'').trim().toLocaleLowerCase('ar')===name.toLocaleLowerCase('ar'))){status('groupStatus','يوجد مجتمع بهذا الاسم بالفعل. اختر اسمًا مختلفًا.','error');return}const result=await dbPost('/groups',{name,description,ownerId:session.user.id,createdAt:Date.now(),category});try{await dbPut(`/groupMembers/${result.name}/${session.user.id}`,'owner')}catch(e){status('groupStatus','تم إنشاء المجتمع لكن تعذّر تأكيد عضوية المالك. سيظهر خيار استعادة العضوية في البطاقة؛ لا تُنشئ نسخة أخرى بالاسم نفسه.','error');console.warn('community owner membership',e.firebaseCode||e.message);await loadGroups();return}$('groupName').value='';$('groupDescription').value='';status('groupStatus','تم إنشاء المجتمع العام.','ok');await loadGroups()}catch(e){status('groupStatus','تعذر التحقق أو إنشاء المجتمع. إذا انقطع الاتصال أثناء الحفظ، راجع القائمة قبل إعادة المحاولة. تأكد من اتصال Firebase وقواعد 1.10.5.','error');console.warn('create community',e.firebaseCode||e.message)}finally{$('createGroupButton').disabled=false}}
async function loadMyStats(){try{const[postsData,followsData,relationsData]=await Promise.all([safeGet('/posts',{}, {orderBy:'"authorId"',equalTo:JSON.stringify(session.user.id)}),safeGet('/follows',{}),safeGet('/friendships',{})]);const posts=Object.keys(postsData||{}).length;const follows=followsData||{};const followers=Object.keys(follows).filter(uid=>!!follows[uid]?.[session.user.id]).length;const following=Object.keys(follows[session.user.id]||{}).length;const friends=mapRows(relationsData).filter(r=>r.status==='accepted'&&(r.requesterId===session.user.id||r.recipientId===session.user.id)).length;const row=$('myStats');row.replaceChildren();for(const[label,value]of[['منشور',posts],['أصدقاء',friends],['متابعون',followers],['يتابع',following]]){const stat=document.createElement('div');stat.className='stat';const strong=document.createElement('strong');strong.textContent=String(value);const caption=document.createElement('span');caption.textContent=label;stat.append(strong,caption);row.append(stat)}}catch(e){console.warn('profile stats',e.firebaseCode||e.message)}}
async function loadProfile(){if(!session)return;try{const uid=session.user.id;if(!profile)profile=profileCache[uid]||readUserCache('profile',30*24*60*60*1000,uid)||{id:uid,displayName:session.user.displayName||session.user.username||'عضو',username:session.user.username||'',bio:'',avatarUrl:''};$('profileName').value=profile.displayName||'';$('profileBio').value=profile.bio||'';$('profileEmail').textContent='@'+(profile.username||session.user.username||'عضو');$('profileAvatarUrl').value=profile.avatarUrl||'';setAvatar($('profileAvatar'),profile);ensureProfile().then(row=>{if(session?.user?.id===uid){$('profileName').value=row.displayName||'';$('profileBio').value=row.bio||'';$('profileEmail').textContent='@'+(row.username||session.user.username||'عضو');$('profileAvatarUrl').value=row.avatarUrl||'';setAvatar($('profileAvatar'),row)}}).catch(()=>{});await Promise.all([loadMyStats(),loadThemePreference(),refreshModerationLists()])}catch(e){status('profileStatus','تعذر تحميل ملفك الشخصي.','error');console.warn('profile',e.firebaseCode||e.message)}}
