async function saveProfile(){const displayName=$('profileName').value.trim(),bio=$('profileBio').value.trim(),avatarUrlRaw=$('profileAvatarUrl').value.trim(),avatarUrl=avatarUrlRaw?httpsUrl(avatarUrlRaw):'';if(displayName.length<2){status('profileStatus','الاسم الظاهر قصير جدًا.','error');return}if(avatarUrlRaw&&!avatarUrl){status('profileStatus','رابط الصورة يجب أن يبدأ بـ https://.','error');return}$('saveProfileButton').disabled=true;try{profile={...profile,displayName,bio,avatarUrl,username:profile.username||session.user.username,createdAt:profile.createdAt||Date.now(),id:session.user.id};const{id,...row}=profile;await dbPut(`/profiles/${session.user.id}`,row);profileCache[session.user.id]=profile;writeUserCache('profile',profile);session.user.displayName=displayName;setStoredSession(session);$('composeName').textContent=nameOf();setAvatar($('composeAvatar'),profile);setAvatar($('profileAvatar'),profile);status('profileStatus','تم حفظ الملف الشخصي.','ok');await loadMyStats()}catch(e){status('profileStatus','تعذر حفظ الملف الشخصي؛ تأكد من نشر القواعد المحدّثة.','error');console.warn('profile update',e.firebaseCode||e.message)}finally{$('saveProfileButton').disabled=false}}
