function openPersonFromBack(){navigate(personReturnPage==='person'?'friends':personReturnPage)}
async function openChat(person){if(!person?.id||!session)return;pendingChatReply=null;renderChatReplyPreview();if(blockedUsers[person.id]){toast('ألغِ حظر هذا العضو قبل مراسلته');return}stopTypingPulse();stopChatPresence();const relation=await safeGet(`/friendships/${friendshipKey(session.user.id,person.id)}`,null);if(relation?.status!=='accepted'){toast('تتاح الرسائل بعد قبول طلب الصداقة');return}const cid=friendshipKey(session.user.id,person.id),members=[session.user.id,person.id].sort();try{let convo=await safeGet(`/conversations/${cid}`,null);if(!convo){convo={memberA:members[0],memberB:members[1],createdAt:Date.now(),updatedAt:Date.now(),lastMessage:'',lastSenderId:''};await dbPut(`/conversations/${cid}`,convo)}await Promise.all(members.map(uid=>dbPut(`/conversationIndex/${uid}/${cid}`,true)));activeChat={id:cid,person,conversation:convo};lastPartnerReadAt=0;showPage('messages');setChatFullscreen(true);$('chatList').classList.add('hidden');$('chatWindow').classList.remove('hidden');await renderActiveChat()}catch(e){toast('تعذر فتح المحادثة؛ تحقق من قواعد الرسائل والحظر.');console.warn('open chat',e.firebaseCode||e.message)}}
async function loadChats(){const box=$('chatList');if(!session)return;if(!box.childElementCount)box.replaceChildren(emptyCard('جارٍ تحميل محادثاتك…'));try{const index=await safeGet(`/conversationIndex/${session.user.id}`,{});const ids=Object.keys(index||{});if(!ids.length){if(!box.childElementCount||box.firstElementChild?.classList.contains('empty'))box.replaceChildren(emptyCard('لا توجد محادثات بعد','افتح ملف صديق ثم اختر «إرسال رسالة».'));return}const conversations=await Promise.all(ids.map(async id=>{const conversation=await safeGet(`/conversations/${id}`,null);if(!conversation)return null;const otherId=conversation.memberA===session.user.id?conversation.memberB:conversation.memberA;const other=profileCache[otherId]||await safeGet(`/profiles/${otherId}`,{displayName:'عضو',id:otherId});profileCache[otherId]=other;return{id,conversation,person:{...other,id:otherId}}}));box.replaceChildren();for(const item of conversations.filter(Boolean).sort((a,b)=>Number(b.conversation.updatedAt||0)-Number(a.conversation.updatedAt||0))){const card=document.createElement('button');card.type='button';card.className='card list-card chat-item'+(activeChat?.id===item.id?' active':'');const av=document.createElement('div');av.className='avatar';setAvatar(av,item.person);const copy=document.createElement('div');copy.className='chat-row-copy';const top=document.createElement('div');top.className='chat-row-top';const name=document.createElement('span');name.className='chat-row-name';name.textContent=item.person.displayName||item.person.username||'عضو';const time=document.createElement('span');time.className='chat-row-time';time.textContent=timeLabel(item.conversation.updatedAt);top.append(name,time);const preview=document.createElement('div');preview.className='chat-row-preview';preview.textContent=item.conversation.lastMessage||'ابدأ المحادثة';copy.append(top,preview);card.append(av,copy);card.onclick=()=>{activeChat=item;setChatFullscreen(true);box.classList.add('hidden');$('chatWindow').classList.remove('hidden');renderActiveChat()};box.append(card)}}catch(e){if(!box.childElementCount)box.replaceChildren(emptyCard('تعذر تحميل الرسائل','انشر قواعد المحادثات المحدّثة وحاول مجددًا.'));console.warn('chats',e.firebaseCode||e.message)}}
async function renderActiveChat(){if(!activeChat)return;chatSearchQuery='';chatSearchIndex=0;$('chatSearchPanel')?.classList.add('hidden');if($('chatSearchInput'))$('chatSearchInput').value='';if($('chatSearchStatus'))$('chatSearchStatus').textContent='';setChatFullscreen(true);stopChatPresence();renderChatReplyPreview();$('chatList').classList.add('hidden');$('chatWindow').classList.remove('hidden');$('chatHeader').replaceChildren();const av=document.createElement('div');av.className='avatar';setAvatar(av,activeChat.person);const copy=document.createElement('div');copy.className='chat-contact-copy';const name=document.createElement('span');name.className='chat-contact-name';name.textContent=activeChat.person.displayName||activeChat.person.username||'عضو';name.onclick=()=>openPerson(activeChat.person.id);const sub=document.createElement('span');sub.id='chatContactStatus';sub.className='chat-contact-sub chat-contact-status';sub.textContent='جارٍ التحقق من الاتصال…';copy.append(name,sub);$('chatHeader').append(av,copy);renderChatAttachmentPreview();await loadMessages(activeChat.id);startChatPresence()}
async function loadMessages(cid,markRead=true,scrollMode='top'){const box=$('chatMessages');const previousScrollTop=box.scrollTop;if(!box.childElementCount)box.replaceChildren(Object.assign(document.createElement('div'),{className:'muted',textContent:'جارٍ تحميل الرسائل…'}));try{const partner=activeChat?.id===cid?activeChat.person.id:'';const [data,readValue]=await Promise.all([dbGet(`/messages/${cid}`,{orderBy:'"createdAt"',limitToLast:'50'}),partner?safeGet(`/conversationReads/${cid}/${partner}`,0):Promise.resolve(0)]);const rows=mapRows(data).sort((a,b)=>Number(a.createdAt||0)-Number(b.createdAt||0));const readAt=Number(readValue||0);lastPartnerReadAt=readAt;box.replaceChildren();if(!rows.length){box.append(emptyCard('ابدأ المحادثة','أرسل رسالة أو صورة لصديقك.'));return}for(const row of rows){const mine=row.authorId===session.user.id,bubble=document.createElement('div');bubble.className='message-bubble'+(mine?' mine':'');bubble.dataset.messageId=row.id;if(row.replyToId){const quote=makeReplyQuote(row);quote.classList.add('message-reply-quote');quote.title='انتقل إلى الرسالة الأصلية';quote.addEventListener('click',event=>{if(event.target.closest('a'))return;const original=[...box.querySelectorAll('.message-bubble')].find(node=>node.dataset.messageId===row.replyToId);original?.scrollIntoView({behavior:'smooth',block:'center'})});bubble.append(quote)}if(row.body){const body=document.createElement('div');renderLinkedText(body,row.body);bubble.append(body)}if(typeof row.attachmentData==='string'&&row.attachmentData.startsWith('data:image/jpeg;base64,')){const image=document.createElement('img');image.className='message-photo';image.src=row.attachmentData;image.alt='صورة مرفقة';image.loading='lazy';image.onclick=()=>{lastChatImage=row.attachmentData;const bridge=window.MoadbookSecureStore;if(bridge?.shareImage)bridge.shareImage(lastChatImage,'moadbook-chat.jpg')};bubble.append(image)}if(mine&&row.body){const editButton=document.createElement('button');editButton.type='button';editButton.className='message-edit-button';editButton.textContent='تعديل';editButton.onclick=()=>editMessage(row);bubble.append(editButton)}const replyButton=document.createElement('button');replyButton.type='button';replyButton.className='message-reply-button';replyButton.textContent='رد';replyButton.setAttribute('aria-label',`الرد على رسالة ${row.authorName||'العضو'}`);replyButton.onclick=()=>selectChatReply(row);bubble.append(replyButton);const meta=document.createElement('div');meta.className='message-meta';const receipt=mine?(readAt>=Number(row.createdAt||0)?' · ✓✓ مقروءة':' · ✓ تم الإرسال'):'';meta.textContent=`${mine?'أنت':row.authorName||'عضو'} · ${timeLabel(row.createdAt)}${row.editedAt?' · معدّلة':''}${receipt}`;bubble.append(meta);box.append(bubble)}if(chatSearchQuery)applyChatSearch();if(scrollMode==='end')box.scrollTop=box.scrollHeight;else if(scrollMode==='preserve')box.scrollTop=previousScrollTop;else box.scrollTop=0;if(markRead&&rows.length){const lastAt=Number(rows[rows.length-1].createdAt||0);safeGet(`/conversationReads/${cid}/${session.user.id}`,0).then(myRead=>{if(lastAt>Number(myRead||0))dbPut(`/conversationReads/${cid}/${session.user.id}`,lastAt).catch(()=>{})})}}catch(e){if(!box.childElementCount)box.replaceChildren(emptyCard('تعذر تحميل الرسائل','تحقق من قواعد المحادثات ومؤشرات القراءة.'));console.warn('messages',e.firebaseCode||e.message)}}
function insertEmojiAt(input,value){if(!input)return;const start=input.selectionStart??input.value.length,end=input.selectionEnd??start;input.setRangeText(value,start,end,'end');input.dispatchEvent(new Event('input',{bubbles:true}));input.focus()}
function clearChatHighlights(){document.querySelectorAll('#chatMessages mark.chat-search-hit').forEach(mark=>mark.replaceWith(document.createTextNode(mark.textContent||'')))}
function applyChatSearch(){clearChatHighlights();const query=String(chatSearchQuery||'').trim();const status=$('chatSearchStatus');if(!query){if(status)status.textContent='';return}const escaped=query.replace(/[.*+?^${}()|[\]\\]/g,'\\$&');let regex;try{regex=new RegExp(escaped,'giu')}catch{return}const root=$('chatMessages');if(!root)return;const walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT,{acceptNode(node){if(!node.nodeValue?.trim()||node.parentElement?.closest('button,.message-meta,mark'))return NodeFilter.FILTER_REJECT;return NodeFilter.FILTER_ACCEPT}});const nodes=[];while(walker.nextNode())nodes.push(walker.currentNode);for(const node of nodes){const text=node.nodeValue||'';regex.lastIndex=0;if(!regex.test(text)){regex.lastIndex=0;continue}regex.lastIndex=0;const frag=document.createDocumentFragment();let last=0,m;while((m=regex.exec(text))){frag.append(document.createTextNode(text.slice(last,m.index)));const mark=document.createElement('mark');mark.className='chat-search-hit';mark.textContent=m[0];frag.append(mark);last=m.index+m[0].length}frag.append(document.createTextNode(text.slice(last)));node.replaceWith(frag)}const hits=[...root.querySelectorAll('mark.chat-search-hit')];chatSearchIndex=Math.min(chatSearchIndex,Math.max(0,hits.length-1));if(status)status.textContent=hits.length?`${chatSearchIndex+1} من ${hits.length}`:'لا توجد نتائج';if(hits[chatSearchIndex])hits[chatSearchIndex].classList.add('current')}
function focusChatSearchHit(direction=0){const hits=[...document.querySelectorAll('#chatMessages mark.chat-search-hit')];if(!hits.length)return;chatSearchIndex=(chatSearchIndex+direction+hits.length)%hits.length;hits.forEach(node=>node.classList.remove('current'));hits[chatSearchIndex].classList.add('current');hits[chatSearchIndex].scrollIntoView({behavior:'smooth',block:'center'});const status=$('chatSearchStatus');if(status)status.textContent=`${chatSearchIndex+1} من ${hits.length}`}
async function sendMessage(){if(!activeChat)return;const body=$('chatInput').value.trim(),attachment=pendingChatImage;if(!body&&!attachment)return;$('chatSend').disabled=true;status('chatStatus','جارٍ الإرسال…');try{stopTypingPulse();const message={authorId:session.user.id,authorName:nameOf().slice(0,60),body,createdAt:Date.now()};if(pendingChatReply)Object.assign(message,{replyToId:pendingChatReply.id,replyToAuthorId:pendingChatReply.authorId,replyToAuthorName:pendingChatReply.authorName,replyToBody:pendingChatReply.body,replyToHasImage:pendingChatReply.hasImage});if(attachment){message.attachmentData=attachment;message.attachmentName='صورة.jpg'}const sent=await dbPost(`/messages/${activeChat.id}`,message);const last=body||'📷 صورة';const updated={...activeChat.conversation,lastMessage:last.slice(0,120),lastSenderId:session.user.id,updatedAt:Date.now()};await dbPut(`/conversations/${activeChat.id}`,updated);activeChat.conversation=updated;pendingChatReply=null;renderChatReplyPreview();await notifyUser(activeChat.person.id,'message',activeChat.id,body?`أرسل لك رسالة: ${body.slice(0,70)}`:'أرسل لك صورة',sent.name);$('chatInput').value='';pendingChatImage=null;lastChatImage=null;renderChatAttachmentPreview();status('chatStatus','');await loadMessages(activeChat.id,true,'end');await loadChats()}catch(e){status('chatStatus','تعذر إرسال الرسالة أو الرد. تحقق من دمج حقول الرد في قواعد Firebase.','error');console.warn('send message',e.firebaseCode||e.message)}finally{$('chatSend').disabled=false}}
const notificationText={like:'أعجب بمنشورك',comment:'علّق على منشورك',friend_request:'أرسل لك طلب صداقة',friend_accept:'قبل طلب صداقتك',follow:'بدأ بمتابعتك',message:'أرسل لك رسالة',group_member:'انضم إلى مجموعتك'};
async function notifyUser(recipientId,type,targetId,text,eventId=''){if(!session||!recipientId||recipientId===session.user.id)return;const value={type,actorId:session.user.id,actorName:nameOf().slice(0,60),recipientId,createdAt:Date.now(),targetId:String(targetId||''),text:String(text||notificationText[type]||'لديك إشعار جديد').slice(0,160),read:false};if(eventId)value.eventId=String(eventId);try{await dbPost(`/notifications/${recipientId}`,value)}catch(e){console.warn('notification write',type,e.firebaseCode||e.message);if(currentPage==='notifications')status('notificationStatus','تعذر حفظ بعض الإشعارات. حدّث قواعد RTDB من ملف القواعد المرفق.','error')}}
function sendWebNotification(row){if(!('Notification'in window)||Notification.permission!=='granted')return;const title=`${row.actorName||'moadbook'} · moadbook`,body=String(row.text||notificationText[row.type]||'لديك إشعار جديد').slice(0,180),options={body,icon:'./moadbook-icon.png',badge:'./moadbook-icon.png',tag:`moadbook-${row.id||Date.now()}`,data:{url:'./index.html?open=notifications'}};const fallback=()=>{try{const n=new Notification(title,options);n.onclick=()=>{window.focus();navigate('notifications');n.close()}}catch(e){console.warn('browser notification unavailable')}};if('serviceWorker'in navigator)navigator.serviceWorker.getRegistration().then(reg=>reg?.showNotification?reg.showNotification(title,options):fallback()).catch(fallback);else fallback()}
function base64UrlToUint8Array(value){const padded=String(value||'').replace(/-/g,'+').replace(/_/g,'/').padEnd(Math.ceil(value.length/4)*4,'=');const raw=atob(padded);return Uint8Array.from(raw,c=>c.charCodeAt(0))}
async function subscribeWebPush(registration){const publicKey=String(window.MOADBOOK_WEB_PUSH_PUBLIC_KEY||'').trim();if(!publicKey||!registration?.pushManager||!session?.user?.id)return false;let subscription=await registration.pushManager.getSubscription();if(!subscription)subscription=await registration.pushManager.subscribe({userVisibleOnly:true,applicationServerKey:base64UrlToUint8Array(publicKey)});const endpoint=subscription.endpoint;const hash=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(endpoint));const id=Array.from(new Uint8Array(hash),b=>b.toString(16).padStart(2,'0')).join('');await dbPut(`/webPushSubscriptions/${session.user.id}/${id}`,{...subscription.toJSON(),updatedAt:Date.now()});return true}
function updateNotificationBadge(rows,announce=false){const unread=rows.filter(row=>row.read!==true).length,badge=$('notificationBadge');badge.textContent=unread>99?'99+':String(unread);badge.classList.toggle('hidden',unread===0);const newest=rows[0];if(lastNotificationId===null){lastNotificationId=newest?.id||'';lastNotificationAt=Number(newest?.createdAt||0);return}if(announce&&newest&&newest.id!==lastNotificationId){const fresh=rows.filter(row=>Number(row.createdAt||0)>lastNotificationAt).sort((a,b)=>Number(b.createdAt||0)-Number(a.createdAt||0));if(fresh.length){toast(`${fresh[0].actorName||'عضو'}: ${fresh[0].text||notificationText[fresh[0].type]||'إشعار جديد'}`);sendWebNotification(fresh[0])}}if(newest){lastNotificationId=newest.id;lastNotificationAt=Math.max(lastNotificationAt,Number(newest.createdAt||0))}}
async function refreshNotificationBadge(announce=false){if(!session)return;try{const data=await dbGet(`/notifications/${session.user.id}`,{orderBy:'"createdAt"',limitToLast:'80'});const rows=mapRows(data).sort((a,b)=>Number(b.createdAt||0)-Number(a.createdAt||0));updateNotificationBadge(rows,announce)}catch(e){console.warn('notification refresh',e.firebaseCode||e.message)}}
function startNotificationPolling(){stopNotificationPolling();lastNotificationId=null;lastNotificationAt=0;refreshNotificationBadge(false);notificationTimer=setInterval(()=>{if(session)refreshNotificationBadge(true)},25000)}
function stopNotificationPolling(){if(notificationTimer){clearInterval(notificationTimer);notificationTimer=null}}
async function loadNotifications(){const box=$('notificationsList');if(!box.childElementCount)box.replaceChildren(emptyCard('جارٍ تحميل الإشعارات…'));status('notificationStatus','');if(!session)return;try{const data=await dbGet(`/notifications/${session.user.id}`,{orderBy:'"createdAt"',limitToLast:'80'});const rows=mapRows(data).sort((a,b)=>Number(b.createdAt||0)-Number(a.createdAt||0));updateNotificationBadge(rows,false);box.replaceChildren();if(!rows.length){box.append(emptyCard('لا توجد إشعارات بعد','ستظهر هنا التفاعلات الجديدة على منشوراتك وطلبات الصداقة والرسائل.'));return}for(const row of rows){const item=document.createElement('button');item.type='button';item.className='card list-card notification-item'+(row.read===true?'':' unread');const av=document.createElement('div');av.className='avatar';setAvatar(av,{id:row.actorId,displayName:row.actorName});const copy=document.createElement('div');copy.className='notification-copy';const title=document.createElement('div');title.className='list-title';title.textContent=row.actorName||'عضو';const text=document.createElement('div');text.className='notification-text';text.textContent=row.text||notificationText[row.type]||'لديك إشعار جديد';const time=document.createElement('div');time.className='notification-time';time.textContent=timeLabel(row.createdAt);copy.append(title,text,time);const dot=document.createElement('span');dot.className='notification-dot'+(row.read===true?' read':'');item.append(av,copy,dot);item.onclick=()=>openNotification(row);box.append(item)}}catch(e){box.replaceChildren(emptyCard('تعذر تحميل الإشعارات','انشر قواعد RTDB الجديدة من الملف المرفق؛ مسار notifications غير متاح في القواعد القديمة.'));status('notificationStatus','تحتاج الإشعارات إلى تحديث قواعد Realtime Database.','error');console.warn('notification inbox',e.firebaseCode||e.message)}}
async function markAllNotificationsRead(){if(!session)return;const button=$('markAllNotifications');button.disabled=true;try{const data=await dbGet(`/notifications/${session.user.id}`,{orderBy:'"createdAt"',limitToLast:'80'});const ids=Object.keys(data||{}).filter(id=>data[id]?.read!==true);await Promise.all(ids.map(id=>dbPut(`/notifications/${session.user.id}/${id}/read`,true)));await loadNotifications();toast('تم تحديد الإشعارات كمقروءة')}catch(e){status('notificationStatus','تعذر تحديث القراءة؛ انشر قواعد RTDB الجديدة.','error')}finally{button.disabled=false}}
async function openConversationFromNotification(cid){const conversation=await dbGet(`/conversations/${cid}`);if(!conversation)throw new Error('CONVERSATION_MISSING');const otherId=conversation.memberA===session.user.id?conversation.memberB:conversation.memberA;const person=await loadProfileById(otherId)||{id:otherId,displayName:'عضو'};activeChat={id:cid,person,conversation};showPage('messages');setChatFullscreen(true);await renderActiveChat()}
async function openNotification(row){try{if(row.read!==true)await dbPut(`/notifications/${session.user.id}/${row.id}/read`,true);await refreshNotificationBadge(false);if(row.type==='message'){await openConversationFromNotification(row.targetId);return}if(row.type==='friend_request'||row.type==='friend_accept'||row.type==='follow'){await openPerson(row.actorId);return}if(row.type==='group_member'){navigate('groups');return}navigate('home');await loadFeed(true)}catch(e){toast('تعذر فتح الإشعار؛ تحقق من القواعد الجديدة.');console.warn('open notification',e.firebaseCode||e.message)}}
function updatePollEditor(){$('pollOptionsEditor').classList.toggle('hidden',$('postType').value!=='poll')}
function normalizeSearch(value){return String(value||'').normalize('NFKC').trim().toLocaleLowerCase('ar')}
function filterPostRows(rows,search,filter){const q=normalizeSearch(search);return rows.filter(row=>{if(q&&!normalizeSearch(`${row.author_name} ${row.body} ${row.mood||''}`).includes(q))return false;if(filter==='media'&&!row.has_media)return false;if(filter==='poll'&&row.post_type!=='poll')return false;if(filter!=='all'&&filter!=='media'&&filter!=='poll'&&row.post_type!==filter)return false;return true})}
function applyFeedFilters(){if(!$('feedList'))return;renderFeed(filterPostRows(feedRows,$('feedSearch')?.value,$('feedFilter')?.value||'all'),$('feedList'),new Set(filterPostRows(feedRows,$('feedSearch')?.value,$('feedFilter')?.value||'all').filter(row=>feedLikes[row.id]?.[session?.user?.id]).map(row=>row.id)))}
function applySavedFilters(){if(!$('savedPostsList'))return;const rows=filterPostRows(savedRows,$('savedSearch')?.value,$('savedFilter')?.value||'all');renderFeed(rows,$('savedPostsList'),new Set(rows.filter(row=>feedLikes[row.id]?.[session?.user?.id]).map(row=>row.id)))}
function renderPoll(row,card){const box=document.createElement('div');box.className='poll-widget';box.append(emptyCard('جارٍ تحميل التصويت…'));card.append(box);loadPollWidget(row,box)}
async function loadPollWidget(row,box){try{const[poll,votes]=await Promise.all([pollCache[row.id]?Promise.resolve(pollCache[row.id]):dbGet(`/polls/${row.id}`),pollVoteCache[row.id]?Promise.resolve(pollVoteCache[row.id]):dbGet(`/pollVotes/${row.id}`)]);if(!box.isConnected)return;if(!poll){box.replaceChildren(emptyCard('هذا المنشور لا يحتوي خيارات تصويت'));return}pollCache[row.id]=poll;pollVoteCache[row.id]=votes||{};const entries=Object.entries(poll.options||{}).sort((a,b)=>Number(a[0])-Number(b[0]));const mine=pollVoteCache[row.id]?.[session.user.id],total=Object.keys(pollVoteCache[row.id]||{}).length;box.replaceChildren();if(entries.length<2){box.append(emptyCard('خيارات التصويت غير مكتملة'));return}for(const[id,label]of entries){const count=Object.values(pollVoteCache[row.id]||{}).filter(v=>String(v)===String(id)).length;const percent=total?Math.round(count*100/total):0;const button=document.createElement('button');button.type='button';button.className='poll-choice'+(String(mine)===String(id)?' selected':'');button.disabled=String(mine)===String(id);const bar=document.createElement('span');bar.className='poll-choice-bar';bar.style.width=mine?`${percent}%`:'0%';const content=document.createElement('span');content.className='poll-choice-content';const title=document.createElement('span');title.textContent=label;content.append(title);if(mine){const result=document.createElement('span');result.textContent=`${count} · ${percent}%`;content.append(result)}button.append(bar,content);button.onclick=()=>castPollVote(row,id,box);box.append(button)}const note=document.createElement('div');note.className='poll-meta';note.textContent=mine?`${total} صوت · نتائج مجمّعة، والتصويت غير سري`:'صوّت، ويمكنك تغيير اختيارك. التصويت غير سري.';box.append(note)}catch(e){box.replaceChildren(emptyCard('تعذر تحميل التصويت','تحقق من نشر قواعد التصويت المحدّثة.'));console.warn('poll load',e.firebaseCode||e.message)}}
async function castPollVote(row,optionId,box){if(!session)return;try{await dbPut(`/pollVotes/${row.id}/${session.user.id}`,String(optionId));pollVoteCache[row.id]=pollVoteCache[row.id]||{};pollVoteCache[row.id][session.user.id]=String(optionId);await loadPollWidget(row,box)}catch(e){toast('تعذر تسجيل التصويت؛ تحقق من قواعد Firebase');console.warn('poll vote',e.firebaseCode||e.message)}}
function setDarkMode(enabled,uid=session?.user?.id){document.documentElement.classList.toggle('dark-mode',!!enabled);const button=$('darkModeToggle');if(button)button.textContent=enabled?'إيقاف الوضع الداكن':'تفعيل الوضع الداكن';if(uid)try{localStorage.setItem(`moadbook-dark-${uid}`,enabled?'true':'false')}catch(e){}}
async function loadThemePreference(){if(!session)return;let remote=null;try{remote=await dbGet(`/userPreferences/${session.user.id}/darkMode`)}catch(e){}let local=null;try{local=localStorage.getItem(`moadbook-dark-${session.user.id}`)}catch(e){}setDarkMode(typeof remote==='boolean'?remote:local==='true',session.user.id)}
async function toggleDarkMode(){const enabled=!document.documentElement.classList.contains('dark-mode');setDarkMode(enabled);if(!session)return;try{await dbPut(`/userPreferences/${session.user.id}/darkMode`,enabled);toast(enabled?'تم تفعيل الوضع الداكن وحفظه لحسابك':'تم إيقاف الوضع الداكن وحفظ اختيارك')}catch(e){toast('حُفظ اختيارك على هذا الجهاز؛ انشر قواعد Firebase لمزامنته') ;console.warn('dark mode preference',e.firebaseCode||e.message)}}
async function refreshModerationLists(){if(!session)return;const[blocks,hidden]=await Promise.all([safeGet(`/blocks/${session.user.id}`,{}),safeGet(`/hiddenAuthors/${session.user.id}`,{})]);blockedUsers=blocks||{};hiddenAuthors=hidden||{}}
async function loadPrivacyTools(){const box=$('privacyItems');if(!box||!session)return;box.replaceChildren();const entries=[...Object.keys(blockedUsers).map(id=>({id,kind:'block'})),...Object.keys(hiddenAuthors).map(id=>({id,kind:'hide'}))];if(!entries.length){box.append(emptyCard('لا توجد حسابات محظورة أو مخفية'));return}for(const entry of entries){const person=await safeGet(`/profiles/${entry.id}`,{displayName:'عضو'});const row=document.createElement('div');row.className='privacy-row';const main=document.createElement('div');main.className='list-main';const title=document.createElement('div');title.className='list-title';title.textContent=person?.displayName||person?.username||'عضو';const sub=document.createElement('div');sub.className='list-sub';sub.textContent=entry.kind==='block'?'حساب محظور':'منشوراته مخفية من موجزك';main.append(title,sub);const action=document.createElement('button');action.textContent=entry.kind==='block'?'إلغاء الحظر':'إلغاء الإخفاء';action.onclick=async()=>{try{await dbDelete(`/${entry.kind==='block'?'blocks':'hiddenAuthors'}/${session.user.id}/${entry.id}`);await refreshModerationLists();await loadPrivacyTools();await loadFeed(true);toast(entry.kind==='block'?'تم إلغاء الحظر':'أُظهرت منشوراته في موجزك')}catch(e){toast('تعذر تحديث إعداد الخصوصية')}};row.append(main,action);box.append(row)}}
