async function toggleBlockUser(uid){if(!session||!uid||uid===session.user.id)return;const path=`/blocks/${session.user.id}/${uid}`;if(blockedUsers[uid]){try{await dbDelete(path);delete blockedUsers[uid];toast('تم إلغاء الحظر');await loadFeed(true);if(currentPage==='settings')await loadPrivacyTools();if(currentPage==='friends')await loadFriends()}catch(e){toast('تعذر إلغاء الحظر','error')}}else{showAppDialog({title:'حظر العضو؟',message:'سيُخفى محتواه وتُمنع التفاعلات والرسائل بينكما.',confirmLabel:'حظر العضو',danger:true,onConfirm:async()=>{try{await dbPut(path,true);blockedUsers[uid]=true;closeAppDialog();toast('تم حظر العضو','success');await loadFeed(true);if(currentPage==='settings')await loadPrivacyTools();if(currentPage==='friends')await loadFriends()}catch(e){toast('تعذر تحديث الحظر؛ تحقق من قواعد Firebase','error');console.warn('block user',e.firebaseCode||e.message)}}})}}
async function reportContent(targetType,targetId){if(!session||!targetId)return;showAppDialog({title:'الإبلاغ عن المحتوى',message:'اختر السبب أو اكتب تفاصيل تساعدنا على المراجعة.',confirmLabel:'إرسال البلاغ',input:true,placeholder:'إساءة، إزعاج، انتحال، محتوى غير مناسب…',onConfirm:async value=>{const reason=String(value||'').trim();if(!reason){toast('اكتب سبب البلاغ أولًا','error');return}try{const reportId=`${Date.now()}_${Math.random().toString(36).slice(2,10)}`;await dbPut(`/reports/${session.user.id}/${reportId}`,{reporterId:session.user.id,targetType,targetId:String(targetId),reason:reason.slice(0,240),createdAt:Date.now(),status:'new'});closeAppDialog();toast('تم استلام البلاغ. شكرًا لمساعدتك في حماية المجتمع.','success')}catch(e){toast('تعذر إرسال البلاغ؛ تحقق من قواعد Firebase','error');console.warn('report',e.firebaseCode||e.message)}}})}
