async function refreshChatPresence(){if(!activeChat||currentPage!=='messages'||!session)return;const cid=activeChat.id,other=activeChat.person.id;try{const[typing,readAt,onlineAt]=await Promise.all([safeGet(`/typing/${cid}/${other}`,0),safeGet(`/conversationReads/${cid}/${other}`,0),safeGet(`/presence/${other}`,0)]);if(!activeChat||activeChat.id!==cid)return;const now=Date.now(),indicator=$('typingIndicator'),isTyping=Number(typing)>now-6500;indicator.textContent=`${activeChat.person.displayName||'العضو'} يكتب الآن`;indicator.classList.toggle('hidden',!isTyping);const status=$('chatContactStatus');if(status){const online=Number(onlineAt)>now-30000;status.textContent=online?'متصل الآن':'غير متصل';status.classList.toggle('online',online)}const remoteRead=Number(readAt||0);if(remoteRead>lastPartnerReadAt){lastPartnerReadAt=remoteRead;await loadMessages(cid,false,'preserve')}}catch(e){console.warn('chat presence',e.firebaseCode||e.message)}}
